BASE = "/mnt/data"
paths = ["/mnt/data/sat_full.py", "/mnt/data/SAT 09SEP25 REFORMULATION.txt", "/mnt/data/Back hallways .txt"]
info = {}
for p in paths:
    try:
        with open(p, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()
        info[p] = {"exists": True, "size": len(content), "preview": content[:1000]}
    except Exception as e:
        info[p] = {"exists": False, "error": str(e)}
info

